import type { ComboboxProps } from "./combobox.types";

import React, { forwardRef, useState, useMemo, useCallback, useEffect, useRef } from "react";
import { Combobox as HeadlessCombobox } from "@headlessui/react";
import { useTheme } from "@theme";
import { clsx } from "clsx";
import {
  autoUpdate,
  flip,
  offset as floatingOffset,
  shift,
  size,
  useFloating,
  useInteractions,
  useRole,
  useClick,
  useDismiss,
  useTransitionStyles,
} from "@floating-ui/react";
import { useUniqueId } from "@system";

import { ComboboxStateContext } from "./hooks/use-combobox-state";
import { ComboboxInteractionContext } from "./hooks/use-combobox-interaction";
import { ComboboxFloatingContext } from "./hooks/use-combobox-floating";
import { ComboboxClasses, StyledCombobox } from "./combobox.styles";
import {
  ComboboxInput,
  ComboboxContent,
  ComboboxItem,
  ComboboxButton,
  ComboboxPrefix,
  ComboboxSuffix,
  ComboboxGroup,
  ComboboxLabel,
  ComboboxDivider,
  ComboboxClearIconButton,
} from "./subcomponents";

const defaultItemToString = (item: unknown): string => {
  if (!item) {
    return "";
  }
  if (typeof item === "string") {
    return item;
  }
  if (typeof item === "object" && "label" in item && typeof item.label === "string") {
    return item.label;
  }
  return String(item);
};

const ComboboxRoot = forwardRef<HTMLDivElement, ComboboxProps>(
  (
    {
      as,
      children,
      value: valueProp,
      defaultValue,
      onChange,
      onQueryChange,
      inputSize = "default",
      disabled,
      side = "bottom",
      sideOffset = 4,
      variant = "default",
      noResults = "No results found",
      showSelectedIndicator = true,
      placeholder,
      id,
      className,
      open: openProp,
      onOpenChange,
      openOnClick = true,
      itemToString = defaultItemToString,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const generatedId = useUniqueId("combobox");
    const comboboxId = id ?? generatedId;
    const inputRef = useRef<HTMLInputElement>(null);

    // State management
    const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? null);
    const [inputValue, setInputValue] = useState(
      defaultValue ? itemToString(defaultValue) : valueProp ? itemToString(valueProp) : "",
    );
    const isControlled = valueProp !== undefined;
    const value = isControlled ? valueProp : uncontrolledValue;

    useEffect(() => {
      if (isControlled) {
        const newLabel = itemToString(value);
        setInputValue(newLabel);
        onQueryChange?.(newLabel);
      }
    }, [value, isControlled, onQueryChange, itemToString]);

    // Floating UI logic
    const [internalOpen, setInternalOpen] = useState(false);
    const isControlledOpen = openProp !== undefined;
    const open = isControlledOpen ? openProp : internalOpen;

    const onOpenChangeHandler = useCallback(
      (newOpenState: boolean) => {
        if (!isControlledOpen) {
          setInternalOpen(newOpenState);
        }
        onOpenChange?.(newOpenState);
      },
      [isControlledOpen, onOpenChange],
    );
    const {
      refs,
      floatingStyles,
      context,
      placement: actualPlacement,
    } = useFloating({
      open,
      onOpenChange: onOpenChangeHandler,
      placement: side,
      whileElementsMounted: autoUpdate,
      middleware: [
        floatingOffset(sideOffset),
        flip(),
        shift(),
        size({
          apply({ rects, elements }) {
            Object.assign(elements.floating.style, {
              width: `${rects.reference.width}px`,
            });
          },
        }),
      ],
    });
    const listRef = React.useRef<Array<HTMLElement | null>>([]);
    const { getReferenceProps, getFloatingProps } = useInteractions([
      useClick(context, { enabled: openOnClick }),
      useDismiss(context),
      useRole(context, { role: "dialog" }),
    ]);
    const { isMounted, styles } = useTransitionStyles(context, {
      duration: 0,
      initial: { opacity: 0 },
    });

    // Interaction logic
    const setValue = useCallback(
      (newValue: typeof value) => {
        if (!isControlled) {
          setUncontrolledValue(newValue);
        }
        onChange?.(newValue);
        const newLabel = itemToString(newValue);
        onQueryChange?.(newLabel);
        setInputValue(newLabel);
        if (newValue !== null && newValue !== undefined) {
          onOpenChangeHandler(false);
        } else {
          onOpenChangeHandler(true);
        }
      },
      [isControlled, onChange, onQueryChange, onOpenChangeHandler, itemToString],
    );

    const clearValue = useCallback(() => {
      setValue(null);
      setInputValue("");
      onQueryChange?.("");
      onOpenChangeHandler(false);
    }, [setValue, onQueryChange, onOpenChangeHandler]);

    const setReference = useCallback(
      (node: HTMLDivElement | null) => {
        (refs.setReference as (node: HTMLDivElement | null) => void)(node);
        if (typeof ref === "function") {
          ref(node);
        } else if (ref) {
          ref.current = node;
        }
      },
      [refs, ref],
    );

    const stateContextValue = useMemo(
      () => ({
        value,
        inputValue,
        isControlled,
        setInputValue,
        setValue,
        showSelectedIndicator,
        noResults,
        inputSize,
        placeholder,
        disabled,
        variant,
        styleSlots: props.styleSlots,
        openOnClick,
        id: comboboxId,
        itemToString,
        as,
        inputRef,
      }),
      [
        value,
        inputValue,
        isControlled,
        setValue,
        showSelectedIndicator,
        noResults,
        inputSize,
        placeholder,
        disabled,
        variant,
        props.styleSlots,
        openOnClick,
        comboboxId,
        itemToString,
        as,
        inputRef,
      ],
    );

    const interactionContextValue = useMemo(
      () => ({
        clearValue,
        onQueryChange,
        onChange,
      }),
      [clearValue, onQueryChange, onChange],
    );

    const floatingContextValue = useMemo(
      () => ({
        floatingStyles,
        floatingContext: context,
        getReferenceProps,
        getFloatingProps,
        isMounted,
        refs,
        styles,
        currentOpenState: open,
        actualPlacement,
        setOpen: onOpenChangeHandler,
        activeIndex: null,
        listRef,
      }),
      [
        floatingStyles,
        context,
        getReferenceProps,
        getFloatingProps,
        isMounted,
        refs,
        styles,
        open,
        actualPlacement,
        onOpenChangeHandler,
      ],
    );

    return (
      <ComboboxStateContext.Provider value={stateContextValue}>
        <ComboboxInteractionContext.Provider value={interactionContextValue}>
          <ComboboxFloatingContext.Provider value={floatingContextValue}>
            <StyledCombobox
              ref={setReference}
              currentTheme={theme}
              variant={variant}
              {...props}
              className={clsx(ComboboxClasses.root, className, {
                [ComboboxClasses.sm]: inputSize === "sm",
              })}
              {...getReferenceProps()}
              aria-expanded={undefined}
            >
              <HeadlessCombobox disabled={disabled} value={value} onChange={setValue}>
                {children}
              </HeadlessCombobox>
            </StyledCombobox>
          </ComboboxFloatingContext.Provider>
        </ComboboxInteractionContext.Provider>
      </ComboboxStateContext.Provider>
    );
  },
);

ComboboxRoot.displayName = "Combobox";

const Combobox = Object.assign(ComboboxRoot, {
  Input: ComboboxInput,
  Content: ComboboxContent,
  Item: ComboboxItem,
  Button: ComboboxButton,
  InputPrefix: ComboboxPrefix,
  InputSuffix: ComboboxSuffix,
  Group: ComboboxGroup,
  Label: ComboboxLabel,
  Divider: ComboboxDivider,
  ClearIconButton: ComboboxClearIconButton,
});

export default Combobox;
